<script setup lang="ts">
import{computed,nextTick,ref}from'vue'
import type{BibleVerse}from'@/api/contracts'
import type{SourceFootnoteAnnotation}from'@/api/sourceAnnotations'
import type{ReaderPreferences}from'@/profile/readerPreferences'
import{defaultPalette,updateWordNote,type WordMark,type StudyPalette}from'@/services/personalStudy'
import{sourceVerseSegments}from'@/services/sourceVerseDisplay'
import{sourceAnnotationMessages}from'@/i18n/sourceAnnotations'
import{createPersonalStudyRepository}from'@/offline/personalStudy'
import{personalStudyMessages}from'@/i18n/personalStudy'
import{useI18n}from'@/i18n'
const props=defineProps<{verse:BibleVerse;code:string;marks:WordMark[];preferences:ReaderPreferences;palette?:StudyPalette;readOnly?:boolean}>(),{language}=useI18n(),labels=computed(()=>sourceAnnotationMessages[language.value]),segments=computed(()=>sourceVerseSegments(props.verse,props.code,props.marks,props.preferences)),note=ref<SourceFootnoteAnnotation>(),modal=ref<HTMLDialogElement>()
const emit=defineEmits<{strong:[number:string]}>()
const wordNote=ref<WordMark>(),wordModal=ref<HTMLDialogElement>(),editing=ref(false),draft=ref(''),failed=ref(false),busy=ref(false),personalLabels=computed(()=>personalStudyMessages[language.value])
const repository=createPersonalStudyRepository()
let wordOpener:HTMLElement|undefined
function openWord(mark:WordMark,event:Event){wordOpener=event.currentTarget as HTMLElement;wordNote.value=mark;editing.value=false;draft.value=mark.note;failed.value=false;void nextTick(()=>wordModal.value?.showModal())}
function closeWord(){wordModal.value?.close();wordNote.value=undefined;wordOpener?.focus({preventScroll:true})}
async function saveWord(){if(!wordNote.value)return;busy.value=true;try{const expected=wordNote.value;await repository.update(value=>updateWordNote(value,expected,draft.value));closeWord()}catch{failed.value=true}finally{busy.value=false}}
let opener:HTMLElement|undefined
function open(item:SourceFootnoteAnnotation,event:Event){opener=event.currentTarget as HTMLElement;note.value=item;void nextTick(()=>modal.value?.showModal())}
function close(){modal.value?.close();note.value=undefined;opener?.focus({preventScroll:true})}
function style(segment:ReturnType<typeof sourceVerseSegments>[number]){const mark=segment.marks.at(-1),palette=props.palette??defaultPalette;return{background:mark?palette[mark.color]?.[props.preferences.night?'night':'day']:undefined,textDecoration:segment.marks.some(mark=>mark.underline)?'underline':undefined}}
</script>
<template><span class="source-verse" :style="{'--source-red':preferences.night?'#ffb3b3':'#9a2430'}"><template v-for="segment in segments" :key="segment.start"><span v-if="segment.paragraph" class="source-paragraph" aria-hidden="true"/><br v-else-if="segment.line"><span v-for="heading in segment.headings" :key="heading.id" class="source-heading">{{heading.text}}</span><sup v-for="footnote in segment.footnotes" :key="footnote.id" role="button" tabindex="0" :aria-label="`${labels.footnote}: ${footnote.marker}`" @click.stop="open(footnote,$event)" @keydown.enter.stop.prevent="open(footnote,$event)" @keydown.space.stop.prevent="open(footnote,$event)">{{footnote.marker??"*"}}</sup><component :is="readOnly?'span':'sup'" v-for="(strong,index) in segment.strongTokens" :key="`${strong.token_order}:${strong.strong_number}:${index}`" :role="readOnly?undefined:'button'" :tabindex="readOnly?undefined:0" :aria-label="strong.strong_number" @pointerdown.stop @click.stop="!readOnly&&emit('strong',strong.strong_number)" @keydown.enter.stop.prevent="!readOnly&&emit('strong',strong.strong_number)" @keydown.space.stop.prevent="!readOnly&&emit('strong',strong.strong_number)">{{strong.strong_number}}</component><span :class="{'source-red':segment.red,'source-added':segment.added,'source-emphasis':segment.emphasis}" :style="style(segment)" :title="preferences.clean?undefined:segment.marks.map(mark=>mark.note).filter(Boolean).join('\n')">{{segment.text}}<sup v-for="mark in segment.marks.filter(mark=>!preferences.clean && mark.note && mark.end===segment.start+segment.text.length)" :key="mark.id" role="button" tabindex="0" :aria-label="`${personalLabels.note}: ${mark.quote}`" @pointerdown.stop @click.stop="openWord(mark,$event)" @keydown.enter.stop.prevent="openWord(mark,$event)" @keydown.space.stop.prevent="openWord(mark,$event)">✎</sup></span></template></span><Teleport to="body"><dialog v-if="note" ref="modal" class="source-footnote" :aria-label="labels.footnote" @cancel.prevent="close"><h3>{{labels.footnote}} {{note.marker??"*"}}</h3><small>{{code}} · {{verse.osis_ref}}</small><p>{{note.body_available && note.text!==null?note.text.replace(/<[^>]*>/gu,''):labels.missing}}</p><small>{{labels.source}}: {{note.source.kind}} · {{note.source.sha256}}</small><button autofocus @click="close">{{labels.back}}</button></dialog><dialog v-if="wordNote" ref="wordModal" class="source-footnote" :aria-label="personalLabels.note" @cancel.prevent="!busy&&closeWord()"><h3>{{personalLabels.note}}</h3><small>{{wordNote.code}} · {{wordNote.osis}}</small><blockquote>{{wordNote.quote}}</blockquote><textarea v-if="editing" v-model="draft" :aria-label="personalLabels.note" rows="5"/><p v-else>{{wordNote.note}}</p><p v-if="failed" role="alert">{{personalLabels.failed}}</p><button v-if="editing" :disabled="busy" @click="saveWord">{{personalLabels.save}}</button><button v-else autofocus @click="editing=true">{{personalLabels.edit}}</button><button :disabled="busy" @click="closeWord">{{personalLabels.close}}</button></dialog></Teleport></template>
<style scoped>.source-red{color:var(--source-red,#9a2430)}.source-footnote textarea{width:100%;box-sizing:border-box}.source-added{font-style:italic;text-decoration:underline dotted;text-underline-offset:3px}.source-emphasis{font-style:italic}.source-heading{display:block;font-weight:700;line-height:1.4;padding:10px 0 6px}.source-paragraph{display:block;height:.75em}.source-verse sup[role=button]{cursor:pointer;color:var(--brand-blue,#1e5aa8);padding:0 3px;font-weight:700}.source-footnote{max-width:min(600px,90vw);max-height:70dvh;overflow:auto;border:1px solid var(--muted);border-radius:12px;background:var(--white);color:var(--ink);padding:16px}.source-footnote::backdrop{background:#0007}.source-footnote p{white-space:pre-wrap;line-height:1.7}.source-footnote button{display:block;margin-top:14px}</style>
